#include "library_credit.h"

namespace library_credit {

patron_account::patron_account() : balance_(0), state_(State::Inactive) {}

void patron_account::enroll() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (state_ == State::Active) {
        throw std::runtime_error("Patron account is already active.");
    }
    state_ = State::Active;
    balance_ = 0;
}

void patron_account::add_credit(int amount) {
    if (amount <= 0) {
        throw std::runtime_error("Amount must be positive.");
    }
    std::lock_guard<std::mutex> lock(mutex_);
    if (state_ != State::Active) {
        throw std::runtime_error("Patron account is not active.");
    }
    balance_ += amount;
}

void patron_account::use_credit(int amount) {
    if (amount <= 0) {
        throw std::runtime_error("Amount must be positive.");
    }
    std::lock_guard<std::mutex> lock(mutex_);
    if (state_ != State::Active) {
        throw std::runtime_error("Patron account is not active.");
    }
    if (amount > balance_) {
        throw std::runtime_error("Insufficient credits.");
    }
    balance_ -= amount;
}

void patron_account::close() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (state_ != State::Active) {
        throw std::runtime_error("Patron account is not active.");
    }
    state_ = State::Closed;
}

int patron_account::credit() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (state_ != State::Active) {
        throw std::runtime_error("Patron account is not active.");
    }
    return balance_;
}

} // namespace library_credit
