#include "energy_reserve.h"

namespace energy_reserve {

reserve_meter::reserve_meter() = default;

void reserve_meter::enable() {
    if (m_state.active.exchange(true, std::memory_order_acq_rel)) {
        throw std::runtime_error("Cannot enable an already active reserve meter.");
    }
    m_state.value.store(0, std::memory_order_relaxed);
}

void reserve_meter::add_units(int amount) {
    if (amount <= 0) {
        throw std::runtime_error("Amount must be positive.");
    }
    if (!m_state.active.load(std::memory_order_acquire)) {
        throw std::runtime_error("Cannot modify an inactive reserve meter.");
    }
    m_state.value.fetch_add(amount, std::memory_order_acq_rel);
}

void reserve_meter::consume_units(int amount) {
    if (amount <= 0) {
        throw std::runtime_error("Amount must be positive.");
    }
    if (!m_state.active.load(std::memory_order_acquire)) {
        throw std::runtime_error("Cannot modify an inactive reserve meter.");
    }

    int current;
    bool success = false;
    do {
        current = m_state.value.load(std::memory_order_acquire);
        if (current < amount) {
            throw std::runtime_error("Insufficient energy units.");
        }
        success = m_state.value.compare_exchange_weak(
            current, current - amount,
            std::memory_order_acq_rel, std::memory_order_acquire);
    } while (!success);
}

void reserve_meter::disable() {
    if (!m_state.active.exchange(false, std::memory_order_acq_rel)) {
        throw std::runtime_error("Cannot disable an inactive reserve meter.");
    }
    m_state.value.store(0, std::memory_order_relaxed);
}

int reserve_meter::remaining_units() {
    if (!m_state.active.load(std::memory_order_acquire)) {
        throw std::runtime_error("Cannot query an inactive reserve meter.");
    }
    return m_state.value.load(std::memory_order_relaxed);
}

