    if (m_state != state::active) {
        throw std::runtime_error("Account is not active");
    }
    if (amount <= 0) {
        throw std::runtime_error("Earn amount must be positive");
    }
    // Atomic addition ensures thread safety
    m_balance.fetch_add(amount, std::memory_order_relaxed);
}

void reward_account::redeem(int amount) {
    if (m_state != state::active) {
        throw std::runtime_error("Account is not active");
    }
    if (amount <= 0) {
        throw std::runtime_error("Redeem amount must be positive");
    }
    // Atomic compare_exchange loop ensures no data race and checks balance
    int current;
    do {
        current = m_balance.load(std::memory_order_relaxed);
        if (current < amount) {
            throw std::runtime_error("Insufficient points");
        }
    } while (!m_balance.compare_exchange_weak(current, current - amount,
                                              std::memory_order_relaxed,
                                              std::memory_order_relaxed));
}

void reward_account::close() {
    if (m_state != state::active) {
        throw std::runtime_error("Account is not active");
    }
    m_state = state::inactive;
    m_balance = 0;
}

int reward_account::points() const {
    if (m_state != state::active) {
        throw std::runtime_error("Account is not active");
    }
