#pragma once

#include <mutex>
#include <stdexcept>

namespace reward_points {
class reward_account {
private:
    std::mutex mtx;
    bool active;
    int points;

public:
    reward_account() : active(false), points(0) {}

    void open() {
        std::lock_guard<std::mutex> lock(mtx);
        if (active) {
            throw std::runtime_error("Account already active");
        }
        active = true;
        points = 0;
    }

    void earn(int amount) {
        std::lock_guard<std::mutex> lock(mtx);
        validate_operation();
        if (amount <= 0) {
            throw std::runtime_error("Earn amount must be positive");
        }
        points += amount;
    }

    void redeem(int amount) {
        std::lock_guard<std::mutex> lock(mtx);
        validate_operation();
        if (amount <= 0) {
            throw std::runtime_error("Redeem amount must be positive");
        }
        if (amount > points) {
            throw std::runtime_error("Insufficient points");
        }
        points -= amount;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mtx);
        if (!active) {
            throw std::runtime_error("Account not active");
        }
        active = false;
    }

    int points() {
        std::lock_guard<std::mutex> lock(mtx);
        validate_operation();
        return points;
    }

private:
