void reward_account::earn(int amount) {
    if (!active_.load(std::memory_order_relaxed)) {
        throw std::runtime_error("Account is inactive");
    }
    if (amount <= 0) {
        throw std::runtime_error("Earn amount must be positive");
    }
    points_.fetch_add(amount, std::memory_order_relaxed);
}

void reward_account::redeem(int amount) {
    if (!active_.load(std::memory_order_relaxed)) {
        throw std::runtime_error("Account is inactive");
    }
    if (amount <= 0) {
        throw std::runtime_error("Redeem amount must be positive");
    }
    // Use a loop to handle potential race conditions not covered by fetch_sub (e.g. underflow)
    // Since we throw if amount > current, we can assume fetch_sub won't underflow, 
    // but a loop ensures atomicity of the check+update.
    while (true) {
        int current = points_.load(std::memory_order_relaxed);
        if (amount <= current) {
            if (points_.compare_exchange_weak(current, current - amount, 
                                             std::memory_order_relaxed, 
                                             std::memory_order_relaxed)) {
                return;
            }
            // CAS failed, retry
        } else {
            throw std::runtime_error("Redeem amount exceeds current points");
        }
    }
}

void reward_account::close() {
    if (!active_.load(std::memory_order_relaxed)) {
        throw std::runtime_error("Account is inactive");
    }
    active_.store(false, std::memory_order_relaxed);
    points_.store(0, std::memory_order_relaxed);
}

