#include "cloud_quota.h"

namespace cloud_quota {

quota_bucket::quota_bucket() : is_active(false), value(0) {}

void quota_bucket::provision() {
    if (!provisioning_flag.test_and_set(std::memory_order_acquire)) {
        if (is_active) {
            provisioning_flag.clear(std::memory_order_release);
            throw std::runtime_error("Bucket already provisioned");
        }
        is_active = true;
        provisioning_flag.clear(std::memory_order_release);
    } else {
        throw std::runtime_error("Concurrent provision detected");
