void quota_bucket::provision() {
    if (!active_.compare_exchange_strong(active_, true)) {
        throw quota_error();
    }
}

void quota_bucket::grant(int amount) {
    if (amount <= 0) {
        throw quota_error();
    }
    std::lock_guard<std::mutex> lock(mtx_);
    value_ += amount;
}

void quota_bucket::consume(int amount) {
    if (amount <= 0) {
        throw quota_error();
    }
    std::lock_guard<std::mutex> lock(mtx_);
    if (value_ < amount) {
        throw quota_error();
    }
    value_ -= amount;
}

void quota_bucket::retire() {
    std::lock_guard<std::mutex> lock(mtx_);
    if (!active_.load()) {
        throw quota_error();
    }
    value_.store(0);
    active_.store(false);
}

int quota_bucket::available() {
    std::lock_guard<std::mutex> lock(mtx_);
    if (!active_.load()) {
        throw quota_error();
