#pragma once

#include <mutex>

namespace secure_wallet {

class wallet_account {
public:
    wallet_account();
    void activate();
    void deposit(int amount);
    void withdraw(int amount);
    void deactivate();
    int balance();

private:
    enum class wallet_state {
        inactive,
        active
    };

    struct wallet_data {
        wallet_state state = wallet_state::inactive;
        int balance = 0;
    };

    wallet_data m_data;
    mutable std::mutex m_mutex;
};

}  // namespace secure_wallet
