#include "secure_wallet.h"
#include <stdexcept>

namespace secure_wallet {

wallet_account::wallet_account() = default;

void wallet_account::activate() {
    std::lock_guard<std::mutex> lock(m_mutex);
    if (m_data.state != wallet_state::inactive) {
        throw std::runtime_error("Wallet is already active");
    }
    m_data.state = wallet_state::active;
    m_data.balance = 0;
}

void wallet_account::deposit(int amount) {
    if (amount <= 0) {
        throw std::runtime_error("Deposit amount must be positive");
    }

    std::lock_guard<std::mutex> lock(m_mutex);
    if (m_data.state != wallet_state::active) {
        throw std::runtime_error("Wallet is not active");
    }
    m_data.balance += amount;
}

void wallet_account::withdraw(int amount) {
    if (amount <= 0) {
        throw std::runtime_error("Withdrawal amount must be positive");
    }

    std::lock_guard<std::mutex> lock(m_mutex);
    if (m_data.state != wallet_state::active) {
        throw std::runtime_error("Wallet is not active");
    }
    if (amount > m_data.balance) {
        throw std::runtime_error("Insufficient funds");
    }
    m_data.balance -= amount;
}

void wallet_account::deactivate() {
    std::lock_guard<std::mutex> lock(m_mutex);
    if (m_data.state != wallet_state::active) {
        throw std::runtime_error("Wallet is not active");
    }
    m_data.state = wallet_state::inactive;
    m_data.balance = 0;
}

int wallet_account::balance() {
    std::lock_guard<std::mutex> lock(m_mutex);
    if (m_data.state != wallet_state::active) {
        throw std::runtime_error("Wallet is not active");
    }
    return m_data.balance;
}

}  // namespace secure_wallet
