#include <stdexcept>
#include <mutex>
#include <condition_variable>
#include <atomic>

namespace workshop_tokens {

class token_box {
public:
    token_box();
    void unlock();
    void add_tokens(int amount);
    void take_tokens(int amount);
    void lock();
    int token_count();

private:
    int count_;
    std::mutex mtx_;
    std::condition_variable cv_;
    std::atomic_flag active_ = ATOMIC_FLAG_INIT;
};

} // namespace workshop_tokens
```

workshop_tokens.cpp
