#include "workshop_tokens.h"

namespace workshop_tokens {

token_box::token_box() : count_(0) {}

void token_box::unlock() {
    if (active_.test_and_set(std::memory_order_acquire)) {
        throw std::runtime_error("Token box is already active");
    }
}

void token_box::add_tokens(int amount) {
    if (amount <= 0) {
        throw std::runtime_error("Amount must be positive");
    }

    std::unique_lock<std::mutex> lock(mtx_);
    if (!active_.test(std::memory_order_acquire)) {
        throw std::runtime_error("Token box is inactive");
    }

    count_ += amount;
    cv_.notify_all();
}

void token_box::take_tokens(int amount) {
    if (amount <= 0) {
        throw std::runtime_error("Amount must be positive");
    }

    std::unique_lock<std::mutex> lock(mtx_);
    cv_.wait(lock, [this, amount]() {
        return !active_.test(std::memory_order_acquire) || 
               count_ >= amount;
    });

    if (!active_.test(std::memory_order_acquire)) {
        throw std::runtime_error("Token box is inactive");
    }

    count_ -= amount;
}

void token_box::lock() {
    if (!active_.test_and_set(std::memory_order_acquire)) {
        throw std::runtime_error("Token box is not active");
    }
    active_.clear(std::memory_order_release);
}

int token_box::token_count() {
    std::lock_guard<std::mutex> lock(mtx_);
    if (!active_.test(std::memory_order_acquire)) {
        throw std::runtime_error("Token box is inactive");
    }
    return count_;
}

} // namespace workshop_tokens
