        validate_and_update(amount, true);
    }

    void spend(int amount) {
        std::lock_guard<std::mutex> lock(m_mutex);
        validate_and_update(amount, false);
    }

    void revoke() {
        std::lock_guard<std::mutex> lock(m_mutex);
        if (!m_active) {
            throw std::runtime_error("Player card not active");
        }
        m_active = false;
    }

    int credits() {
        std::lock_guard<std::mutex> lock(m_mutex);
        if (!m_active) {
            throw std::runtime_error("Player card not active");
        }
        return m_credits;
    }

private:
