        if (amount <= 0) {
            throw std::runtime_error("Amount must be positive");
        }

        if (!m_active) {
            throw std::runtime_error("Player card not active");
        }

        if (is_load) {
            m_credits += amount;
        } else {
            if (amount > m_credits) {
                throw std::runtime_error("Insufficient credits");
            }
            m_credits -= amount;
        }
    }
